const id = (name) => name.replaceAll(/[^a-zA-Z0-9]/g, "_");
const escape = (value) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
export function renderMermaid(documents, relationships, complete) {
  const names = new Set(documents.map((d) => d.name));
  const lines = [
    `# Booklet document schema ? ${complete ? "complete" : "simple core"}`,
    "",
    "<!-- Generated by npm run docs:booklet-model; edit document model sources. -->",
    "",
    "[Canonical model](model.md) ? [Concrete JSON example](model-document-example.json)",
    "",
    "The embedded production index, lifecycle, media and MCP services are implemented in T14-T17. Later workflow/delivery work retains explicit labels. Each box is a document boundary or a labeled existing service view; indented objects and arrays belong inside it. There are no separate Subject or Artifact collections. Arrows are cross-document references, not execution order.",
    "",
    complete
      ? "All maintained domain document summaries are shown. Economy reuses Unibase; this is not a complete inventory of its internal collections. Later-task proposals and unresolved execution details retain explicit labels."
      : "Core document boundaries and selected nested fields. Complete details: [complete schema](model-complete-mermaid.md).",
    "",
    "```mermaid",
    '%%{init: {"theme":"base","themeVariables":{"primaryColor":"#f1f5f9","primaryTextColor":"#172033","primaryBorderColor":"#64748b","lineColor":"#64748b","edgeLabelBackground":"#ffffff"},"flowchart":{"htmlLabels":false,"useMaxWidth":false}}}%%',
    "flowchart TB",
  ];
  for (const doc of documents) {
    let fields = doc.fields;
    if (!complete) {
      if (doc.name === "Production")
        fields = [
          "_id / bookletId / orderId / revisionChargeId? / version",
          "brief {} / creativeConfigSnapshot {}",
          "subjects[] {",
          "  id / kind / label",
          "  artifacts[] {id, kind, currentRevisionId, acceptedRevisionId}",
          "}",
          "stageLocks {} / mutationLease? {}",
        ];
      else if (doc.name === "Artifact revision")
        fields = [
          "_id / productionId / artifactId / subjectId",
          "kind / ordinal / contentHash",
          "content {panels[] {lettering[]} or other typed payload}",
          "sources[] / assets[] / provenance {}",
        ];
      else fields = doc.fields.slice(0, 4);
    }
    lines.push(
      `  ${id(doc.name)}["${[doc.name, doc.status, ...fields].map(escape).join("<br/>")}"]`,
    );
  }
  for (const [from, to, label] of relationships) {
    if (names.has(from) && names.has(to))
      lines.push(`  ${id(from)} -->|"${escape(label)}"| ${id(to)}`);
  }
  lines.push("```", "");
  return lines.join("\n");
}
